    fun importProjectJson(uri: Uri) {
        viewModelScope.launch {
            runCatching {
                val txt = withContext(Dispatchers.IO) {
                    getApplication<Application>().contentResolver.openInputStream(uri)?.bufferedReader()?.use { it.readText() }
                } ?: throw IllegalStateException("Файл не похож на проект VoiceComic")
                val kx = kotlinx.serialization.json.Json { ignoreUnknownKeys = true; isLenient = true }
                val root = kx.parseToJsonElement(txt) as? kotlinx.serialization.json.JsonObject
                    ?: throw IllegalStateException("Файл не похож на проект VoiceComic")
                val proj = root["project"] ?: throw IllegalStateException("Файл не похож на проект VoiceComic")
                val imported = kx.decodeFromJsonElement(Project.serializer(), proj)
                edit { p ->
                    p.copy(
                        kind = imported.kind,
                        roles = imported.roles.ifEmpty { p.roles },
                        pages = p.pages.zip(imported.pages).map { (old, imp) ->
                            old.copy(
                                bubbles = old.bubbles.zip(imp.bubbles).map { (ob, ib) -> ob.copy(text = ib.text, tr = ib.tr) },
                                name = old.name.ifEmpty { imp.name }
                            )
                        }
                    )
                }
                say("Сценарий загружен")
            }.onFailure { say(it.message ?: "Ошибка импорта", "err") }
        }
    }

    // ---------- чат ----------

    private fun chatFile() = File(store.projectDir(projectId), "chat.json")

    private fun loadChat() {
        val f = chatFile()
        if (!f.exists()) {
            chatSessions = listOf("s" + System.currentTimeMillis())
            chatCurrent = chatSessions.first()
            return
        }
        runCatching {
            val root = kotlinx.serialization.json.Json.parseToJsonElement(f.readText())
                    as kotlinx.serialization.json.JsonObject
            chatSessions = (root["sessions"] as? kotlinx.serialization.json.JsonArray)
                ?.mapNotNull { (it as? kotlinx.serialization.json.JsonPrimitive)?.content }
                ?: emptyList()
            chatCurrent = (root["current"] as? kotlinx.serialization.json.JsonPrimitive)?.content ?: ""
            chatMessages = parseMessages(root["messages"])
        }
    }

    private fun parseMessages(el: kotlinx.serialization.json.JsonElement?): List<ChatMsg> {
        val arr = el as? kotlinx.serialization.json.JsonArray ?: return emptyList()
        return arr.mapNotNull { m ->
            val o = m as? kotlinx.serialization.json.JsonObject ?: return@mapNotNull null
            ChatMsg(
                role = o["role"]?.toString()?.trim('"') ?: "user",
                content = o["content"]?.toString()?.trim('"') ?: "",
                files = (o["files"] as? kotlinx.serialization.json.JsonArray)
                    ?.mapNotNull { (it as? kotlinx.serialization.json.JsonPrimitive)?.content } ?: emptyList()
            )
        }
    }

    private fun saveChat() {
        val kx = kotlinx.serialization.json.buildJsonObject {
            put("current", kotlinx.serialization.json.JsonPrimitive(chatCurrent))
            put("sessions", kotlinx.serialization.json.buildJsonArray {
                chatSessions.forEach { add(kotlinx.serialization.json.JsonPrimitive(it)) }
            })
            put("messages", kotlinx.serialization.json.buildJsonArray {
                chatMessages.forEach { msg ->
                    add(kotlinx.serialization.json.buildJsonObject {
                        put("role", kotlinx.serialization.json.JsonPrimitive(msg.role))
                        put("content", kotlinx.serialization.json.JsonPrimitive(msg.content))
                        put("files", kotlinx.serialization.json.buildJsonArray {
                            msg.files.forEach { add(kotlinx.serialization.json.JsonPrimitive(it)) }
                        })
                    })
                }
            })
        }
        runCatching { chatFile().writeText(kx.toString()) }
    }

    fun newChatSession() {
        val id = "s" + System.currentTimeMillis()
        chatSessions = listOf(id) + chatSessions
        chatCurrent = id
        chatMessages = emptyList()
        saveChat()
    }

    fun selectChatSession(id: String) {
        chatCurrent = id
        saveChat()
    }

    fun deleteChatSession() {
        chatSessions = chatSessions.filterNot { it == chatCurrent }
        if (chatSessions.isEmpty()) newChatSession()
        chatMessages = emptyList()
        saveChat()
    }

    // ---------- чат: агентный цикл с инструментами ----------

    private var agentJob: Job? = null

    val chatBusy: Boolean get() = chatTyping

    fun stopChat() {
        agentJob?.cancel()
        agent.stop()
        chatTyping = false
    }

    fun sendChatWithAttachments(text: String) {
        val attach = chatAttach
        chatAttach = emptyList()
        if (text.isBlank() && attach.isEmpty()) return
        if (chatTyping) {
            say("Дождитесь ответа или нажмите «Стоп»", "err")
            return
        }
        val userMsg = ChatMsg("user", text, files = attach.map { it.first }, images = attach.indices.toList())
        chatMessages = chatMessages + userMsg
        saveChat()
        chatTyping = true
        val settingsSnapshot = settings
        agentJob = viewModelScope.launch {
            val events = ArrayList<AgentEvent>()
            try {
                val history = chatMessages
                    .filter { it.role == "user" || it.role == "ai" }
                    .dropLast(1)
                    .takeLast(10)
                    .map { Msg(if (it.role == "user") "user" else "assistant", it.content) }
                val imageData = attach.mapNotNull { if (it.third.isNotEmpty()) it.third else null }
                agent.run(settingsSnapshot, history, text, imageData) { ev ->
                    events.add(ev)
                    when (ev) {
                        is AgentEvent.Text -> chatMessages = chatMessages + ChatMsg("ai", ev.text)
                        is AgentEvent.Reasoning -> appendToLastAi { it.copy(reasoning = ev.text) }
                        is AgentEvent.ToolStart -> appendToLastAi {
                            it.copy(tools = it.tools + ToolRun(ev.name, "запускается…", true))
                        }

                        is AgentEvent.ToolDone -> markLastTool(ev.name, ev.summary, true)
                        is AgentEvent.ToolError -> markLastTool(ev.name, ev.message, false)
                        is AgentEvent.Failed -> {
                            chatMessages = chatMessages + ChatMsg("err", ev.message)
                        }

                        else -> Unit
                    }
                }
            } catch (e: Throwable) {
                chatMessages = chatMessages + ChatMsg("err", "Ошибка: ${e.message}")
            } finally {
                chatTyping = false
                saveChat()
            }
        }
    }

    private fun appendToLastAi(block: (ChatMsg) -> ChatMsg) {
        if (chatMessages.lastOrNull()?.role != "ai") {
            chatMessages = chatMessages + ChatMsg("ai", "", tools = emptyList())
        }
        chatMessages = chatMessages.dropLast(1) + block(chatMessages.last())
    }

    private fun markLastTool(name: String, summary: String, ok: Boolean) {
        appendToLastAi { m ->
            val idx = m.tools.indexOfLast { it.summary == "запускается…" }
            if (idx < 0) m.copy(tools = m.tools + ToolRun(name, summary, ok))
            else m.copy(tools = m.tools.toMutableList().also { it[idx] = ToolRun(name, summary, ok) })
        }
    }

    /** Содержимое сообщения для запроса к модели: файлы — текстом, картинки — картинками. */
    private fun ChatMsg.asRequestText(): String {
        if (files.isEmpty()) return content
        return content
    }

    // ---------- каталог моделей ----------

    fun refreshCatalog(silent: Boolean = false) {
        viewModelScope.launch {
            if (!silent) progress = Prog(0.3, "Обновление каталога моделей…")
            val models = com.voicecomic.app.ai.Providers.refreshFromNetwork(getApplication(), http)
            if (!silent) progress = null
            say(
                if (models > 0) "Каталог обновлён: моделей $models" else "Каталог не обновился",
                if (models > 0) "ok" else "err"
            )
        }
    }

    /** Модель пропала из каталога — молча подтягиваем свежий и повторяем. */
    fun ensureModelExists(): Boolean {
        if (com.voicecomic.app.ai.Providers.isValidModel(settings)) return true
        viewModelScope.launch {
            com.voicecomic.app.ai.Providers.refreshFromNetwork(getApplication(), http)
            if (!com.voicecomic.app.ai.Providers.isValidModel(settings)) {
                say("Модель ${settings.aimodel} не найдена в каталоге — обнови каталог или выбери другую", "err")
            }
        }
        return false
    }

    // ---------- workspace ----------

    var workspaceTick by mutableIntStateOf(0)

    // ---------- пользовательские инструменты и навыки ----------

    fun customTools(): List<com.voicecomic.app.chat.CustomTool> = tools.registry().tools()

    fun deleteCustomTool(id: String) {
        tools.registry().delete(id)
        say("Инструмент удалён")
    }

    /**
     * Создаёт пользовательский инструмент. kind=http — запрос к API (например GitHub),
     * kind=shell — команда через sh в папке workspace. Параметры уходят модели как схема.
     */
    fun addCustomTool(
        name: String,
        kind: String,
        description: String,
        paramLines: String,
        spec: String
    ) {
        val clean = name.trim().replace(Regex("[^A-Za-z0-9_-]"), "_")
        if (clean.isEmpty()) {
            say("Имя инструмента не задано", "err")
            return
        }
        val params = paramLines.split('\n')
            .map { it.trim() }
            .filter { it.isNotEmpty() }
            .map { line ->
                val p = line.split('|', ':').map { it.trim() }
                com.voicecomic.app.chat.ToolParam(
                    name = p.getOrNull(0).orEmpty(),
                    description = p.getOrNull(1).orEmpty(),
                    required = p.getOrNull(2)?.lowercase() != "opt"
                )
            }
            .filter { it.name.isNotEmpty() }
        val tool = com.voicecomic.app.chat.CustomTool(
            id = newId(),
            name = clean,
            description = description.trim().ifEmpty { "пользовательский инструмент" },
            kind = kind,
            params = params,
            method = if (kind == "http") spec.substringBefore(' ').uppercase().ifEmpty { "GET" } else "GET",
            url = if (kind == "http") spec.substringAfter(' ', "").trim().ifEmpty { spec.trim() } else "",
            body = if (kind == "http") bodyFrom(spec) else "",
            command = if (kind == "shell") spec.trim() else ""
        )
        tools.registry().upsert(tool)
        say("Инструмент $clean добавлен: ${params.size} параметров")
    }

    private fun bodyFrom(spec: String): String {
        val i = spec.indexOf('\n')
        return if (i > 0) spec.substring(i + 1).trim() else ""
    }

    fun addSkillFromFile(uri: android.net.Uri, nameOf: (android.net.Uri) -> String) {
        viewModelScope.launch {
            val name = nameOf(uri)
            val text = withContext(Dispatchers.IO) {
                runCatching {
                    getApplication<Application>().contentResolver.openInputStream(uri)?.bufferedReader()?.use { it.readText() }
                }.getOrNull()
            }
            if (text.isNullOrBlank()) {
                say("Не удалось прочитать файл навыка", "err")
            } else {
                say(tools.registry().addSkill(name, text))
                workspaceTick++
            }
        }
    }

    fun userSkills(): List<String> = tools.registry().userSkills()

package com.voicecomic.app.audio

import java.io.File
import java.io.RandomAccessFile
import kotlin.math.abs
import kotlin.math.ceil
import kotlin.math.max
import kotlin.math.min
import kotlin.math.roundToInt
import kotlin.math.sqrt

/** Утилиты PCM: моно-микс, ресемплинг, обрезка тишины, нарезка по паузам, WAV. */
object Pcm {

    const val MIX_RATE = 44100

    data class Trim(val start: Int, val end: Int)

    /** Склеивает все каналы усреднением (как в веб-версии). */
    fun toMono(buffers: Array<FloatArray>, frames: Int): FloatArray {
        val ch = buffers.size
        if (ch == 1) return buffers[0].let { if (it.size >= frames) it.copyOf(frames) else it.copyOf(frames) }
        val out = FloatArray(frames)
        for (c in buffers) {
            for (i in 0 until min(frames, c.size)) out[i] += c[i] / ch
        }
        return out
    }

    /** Линейный ресемплинг, точная копия resampleLinear из веб-версии. */
    fun resampleLinear(src: FloatArray, fromSr: Int, toSr: Int): FloatArray {
        if (fromSr == toSr) return src
        val step = fromSr.toDouble() / toSr
        val n = (src.size * toSr / fromSr.toDouble()).toInt().coerceAtLeast(0)
        val out = FloatArray(n)
        for (i in 0 until n) {
            val x = i * step
            val i0 = x.toInt()
            val i1 = min(i0 + 1, src.size - 1)
            val t = (x - i0).toFloat()
            out[i] = src[i0.coerceIn(0, src.size - 1)] * (1 - t) + src[i1] * t
        }
        return out
    }

    /**
     * Обрезка тишины по окнам. threshold — пиковый порог, margin — отступ в секундах.
     * Покрывает util.trimSilence и engine.TRIM (порог/отступ задаются вызывающим).
     */
    fun trimSilence(
        samples: FloatArray,
        sr: Int,
        threshold: Double = 0.02,
        margin: Double = 0.09,
        winMs: Int = 10
    ): Trim {
        val n = samples.size
        if (n == 0) return Trim(0, 0)
        val win = max(1, (sr * winMs / 1000.0).toInt())
        val pad = max(1, (sr * margin).toInt())
        var start = 0
        var end = 0
        var i = 0
        var found = false
        while (i + win <= n) {
            var peak = 0f
            var k = i
            while (k < i + win) {
                val v = abs(samples[k])
                if (v > peak) peak = v
                k++
            }
            if (peak > threshold) {
                start = max(0, i - pad)
                found = true
                break
            }
            i += win
        }
        if (!found) return Trim(0, 0)
        i = n
        var foundEnd = false
        while (i - win >= 0) {
            var peak = 0f
            var k = max(0, i - win)
            while (k < i) {
                val v = abs(samples[k])
                if (v > peak) peak = v
                k++
            }
            if (peak > threshold) {
                end = min(n, i + pad)
                foundEnd = true
                break
            }
            i -= win
        }
        if (!foundEnd) end = n
        return Trim(start, max(start, end))
    }

    data class Seg(val startS: Double, val endS: Double)

    /**
     * Нарезка по тишине. window активности — RMS > threshold, тишина длиной не меньше
     * minSilence завершает фразу, фраза короче minClip выбрасывается, длиннее maxClip режется.
     */
    fun sliceSegments(
        samples: FloatArray,
        sr: Int,
        threshold: Double = 0.02,
        minSilence: Double = 0.32,
        minClip: Double = 0.3,
        maxClip: Double = 16.0,
        winMs: Int = 40
    ): List<Seg> {
        val n = samples.size
        if (n == 0) return emptyList()
        val win = max(1, (sr * winMs / 1000.0).toInt())
        val steps = n / win
        val active = BooleanArray(steps + 1)
        for (k in 0 until steps) {
            var sum = 0.0
            val base = k * win
            for (j in base until base + win) {
                val v = samples[j].toDouble()
                sum += v * v
            }
            active[k] = (sum / win) > threshold * threshold
        }
        val minSil = max(1, (minSilence / (winMs / 1000.0)).toInt())
        val out = ArrayList<Seg>()
        var inClip = false
        var cStart = 0
        var cEnd = 0
        var silence = 0
        for (k in 0..steps) {
            val act = k < steps && active[k]
            if (act) {
                if (!inClip) {
                    inClip = true
                    cStart = k
                }
                silence = 0
                cEnd = k
            } else if (inClip) {
                silence++
                if (silence >= minSil) {
                    emit(out, cStart, cEnd, win, sr, n, minClip, maxClip)
                    inClip = false
                }
            }
        }
        if (inClip) emit(out, cStart, cEnd, win, sr, n, minClip, maxClip)
        return out
    }

    private fun emit(
        out: MutableList<Seg>, cStart: Int, cEnd: Int, win: Int, sr: Int,
        n: Int, minClip: Double, maxClip: Double
    ) {
        val s = cStart * win.toDouble() / sr
        val e = min(n, (cEnd + 1) * win).toDouble() / sr
        if (e - s >= minClip) out.add(Seg(s, min(e, s + maxClip)))
    }

    fun floatToPcm16(src: FloatArray, from: Int = 0, count: Int = src.size - from): ShortArray {
        val n = min(count, src.size - from).coerceAtLeast(0)
        val out = ShortArray(n)
        for (i in 0 until n) {
            val v = src[from + i].coerceIn(-1f, 1f)
            out[i] = (if (v < 0) v * 0x8000 else v * 0x7fff).toInt().toShort()
        }
        return out
    }

    fun pcm16ToFloat(src: ShortArray): FloatArray {
        val out = FloatArray(src.size)
        for (i in src.indices) out[i] = src[i] / 32768f
        return out
    }

    /** WAV 16-bit mono — тот же формат, что samplesToWav в веб-версии. */
    fun writeWav(file: File, pcm: ShortArray, sr: Int) {
        val dataLen = pcm.size * 2
        file.parentFile?.mkdirs()
        RandomAccessFile(file, "rw").use { raf ->
            raf.setLength(0)
            val h = ByteArray(44)
            fun putStr(off: Int, s: String) = s.toByteArray(Charsets.US_ASCII).copyInto(h, off)
            fun putLe32(off: Int, v: Int) {
                h[off] = (v and 0xff).toByte(); h[off + 1] = ((v shr 8) and 0xff).toByte()
                h[off + 2] = ((v shr 16) and 0xff).toByte(); h[off + 3] = ((v shr 24) and 0xff).toByte()
            }

            fun putLe16(off: Int, v: Int) {
                h[off] = (v and 0xff).toByte(); h[off + 1] = ((v shr 8) and 0xff).toByte()
            }

            putStr(0, "RIFF"); putLe32(4, 36 + dataLen); putStr(8, "WAVE")
            putStr(12, "fmt "); putLe32(16, 16); putLe16(20, 1); putLe16(22, 1)
            putLe32(24, sr); putLe32(28, sr * 2); putLe16(32, 2); putLe16(34, 16)
            putStr(36, "data"); putLe32(40, dataLen)
            raf.write(h)
            val bytes = ByteArray(dataLen)
            var i = 0
            while (i < pcm.size) {
                val v = pcm[i].toInt()
                bytes[i * 2] = (v and 0xff).toByte()
                bytes[i * 2 + 1] = ((v shr 8) and 0xff).toByte()
                i++
            }
            raf.write(bytes)
        }
    }

    fun readWav(file: File): Pair<FloatArray, Int>? {
        val bytes = file.readBytes()
        if (bytes.size < 44) return null
        val sr = (bytes[24].toInt() and 0xff) or ((bytes[25].toInt() and 0xff) shl 8) or
            ((bytes[26].toInt() and 0xff) shl 16) or ((bytes[27].toInt() and 0xff) shl 24)
        val channels = (bytes[22].toInt() and 0xff) or ((bytes[23].toInt() and 0xff) shl 8)
        val bits = (bytes[34].toInt() and 0xff) or ((bytes[35].toInt() and 0xff) shl 8)
        if (bits != 16) return null
        // ищем начало data-чанка
        var off = 12
        while (off + 8 <= bytes.size) {
            val id = String(bytes, off, 4, Charsets.US_ASCII)
            val size = (bytes[off + 4].toInt() and 0xff) or ((bytes[off + 5].toInt() and 0xff) shl 8) or
                ((bytes[off + 6].toInt() and 0xff) shl 16) or ((bytes[off + 7].toInt() and 0xff) shl 24)
            if (id == "data") {
                off += 8
                val frames = (bytes.size - off) / 2 / max(1, channels)
                val out = FloatArray(frames)
                var i = 0
                while (i < frames) {
                    var acc = 0f
                    for (c in 0 until max(1, channels)) {
                        val p = off + (i * channels + c) * 2
                        if (p + 1 >= bytes.size) break
                        val v = ((bytes[p].toInt() and 0xff) or ((bytes[p + 1].toInt() and 0xff) shl 8)).toShort()
                        acc += v / 32768f
                    }
                    out[i] = acc / max(1, channels)
                    i++
                }
                return out to sr
            }
            off += 8 + size + (size and 1)
        }
        return null
    }

    fun durationSeconds(pcm: FloatArray, sr: Int): Double = pcm.size.toDouble() / sr

    fun rms(samples: FloatArray, from: Int, len: Int): Double {
        val n = min(len, samples.size - from).coerceAtLeast(0)
        if (n == 0) return 0.0
        var sum = 0.0
        for (i in 0 until n) {
            val v = samples[from + i].toDouble()
            sum += v * v
        }
        return sqrt(sum / n)
    }

    /** Оценка длительности реплики без озвучки — 13 символов/с, как в веб-версии. */
    fun estimateSpeakDuration(text: String): Double {
        if (text.isBlank()) return 0.0
        val len = text.length
        val base = max(1.1, min(14.0, len / 13.0 + 0.55))
        return base + if (text.any { it.isWhitespace() }) 0.15 else 0.0
    }

    fun framesFor(duration: Double, sr: Int): Int = ceil(duration * sr).toInt()
}

package com.voicecomic.app.audio

import android.media.AudioFormat
import android.media.MediaCodec
import android.media.MediaExtractor
import android.media.MediaFormat
import java.io.File
import java.nio.ByteBuffer
import kotlin.math.max

/** Декодер звука/видео через MediaExtractor + MediaCodec (замена decodeAudioData). */
object MediaAudioDecoder {

    class Result(val samples: FloatArray, val sr: Int, val duration: Double)

    fun decode(file: File, maxSeconds: Double = 0.0): Result? = runCatching {
        val extractor = MediaExtractor()
        extractor.setDataSource(file.absolutePath)

        var track = -1
        var format: MediaFormat? = null
        for (i in 0 until extractor.trackCount) {
            val f = extractor.getTrackFormat(i)
            val mime = f.getString(MediaFormat.KEY_MIME) ?: continue
            if (mime.startsWith("audio/")) {
                track = i
                format = f
                break
            }
        }
        if (track < 0 || format == null) {
            extractor.release()
            return null
        }
        extractor.selectTrack(track)
        val mime = format.getString(MediaFormat.KEY_MIME)!!
        val codec = MediaCodec.createDecoderByType(mime)
        codec.configure(format, null, null, 0)
        codec.start()

        val chunks = ArrayList<FloatArray>()
        var total = 0
        var srcSr = format.getInteger(MediaFormat.KEY_SAMPLE_RATE)
        var srcCh = format.getInteger(MediaFormat.KEY_CHANNEL_COUNT)
        var sawInputEos = false
        var sawOutputEos = false
        var gotFormat = false
        val info = MediaCodec.BufferInfo()
        var pcmEncoding = AudioFormat.ENCODING_PCM_16BIT
        val limitFrames = if (maxSeconds > 0) (maxSeconds * srcSr).toInt() else Int.MAX_VALUE

        while (!sawOutputEos) {
            if (!sawInputEos) {
                val inIdx = codec.dequeueInputBuffer(10_000)
                if (inIdx >= 0) {
                    val buf = codec.getInputBuffer(inIdx)
                    val size = if (buf != null) extractor.readSampleData(buf, 0) else -1
                    if (size < 0) {
                        codec.queueInputBuffer(
                            inIdx, 0, 0, 0, MediaCodec.BUFFER_FLAG_END_OF_STREAM
                        )
                        sawInputEos = true
                    } else {
                        codec.queueInputBuffer(inIdx, 0, size, extractor.sampleTime, 0)
                        extractor.advance()
                    }
                }
            }
            val outIdx = codec.dequeueOutputBuffer(info, 10_000)
            if (outIdx == MediaCodec.INFO_OUTPUT_FORMAT_CHANGED) {
                val of = codec.outputFormat
                srcSr = of.getInteger(MediaFormat.KEY_SAMPLE_RATE)
                srcCh = of.getInteger(MediaFormat.KEY_CHANNEL_COUNT)
                pcmEncoding = of.getInteger(MediaFormat.KEY_PCM_ENCODING)
                gotFormat = true
                continue
            }
            if (outIdx >= 0) {
                if (info.size > 0 && total < limitFrames) {
                    val out = codec.getOutputBuffer(outIdx)
                    if (out != null) {
                        out.position(info.offset)
                        out.limit(info.offset + info.size)
                        val n = info.size / 2
                        val shorts = ShortArray(n)
                        out.asShortBuffer().get(shorts, 0, n)
                        val frames = n / max(1, srcCh)
                        val mono = FloatArray(frames)
                        for (f in 0 until frames) {
                            var acc = 0f
                            for (c in 0 until srcCh) {
                                val idx = f * srcCh + c
                                if (idx < n) acc += shorts[idx] / 32768f
                            }
                            mono[f] = acc / max(1, srcCh)
                        }
                        chunks.add(mono)
                        total += frames
                    }
                }
                codec.releaseOutputBuffer(outIdx, false)
                if (info.flags and MediaCodec.BUFFER_FLAG_END_OF_STREAM != 0) sawOutputEos = true
            }
            if (chunks.sumOf { it.size } > limitFrames) break
        }
        codec.stop()
        codec.release()
        extractor.release()

        @Suppress("UNUSED_EXPRESSION") gotFormat
        @Suppress("UNUSED_EXPRESSION") pcmEncoding
        val samples = FloatArray(total)
        var off = 0
        for (c in chunks) {
            System.arraycopy(c, 0, samples, off, c.size)
            off += c.size
        }
        Result(samples, srcSr, samples.size.toDouble() / srcSr)
    }.getOrNull()

    /** Декодер в PCM 16 kHz моно для MediaCodec-энкодера AAC. */
    fun toPcm16(file: File): Pair<ShortArray, Int>? {
        val r = decode(file) ?: return null
        val target = if (r.sr == Pcm.MIX_RATE) r.samples else Pcm.resampleLinear(r.samples, r.sr, Pcm.MIX_RATE)
        return Pcm.floatToPcm16(target) to Pcm.MIX_RATE
    }

}

